<?php

declare(strict_types=1);

use FMonitor2\YiiRuntime\ViewSupport;
use yii\helpers\Html;

$dateLabel=static fn(?string$value):string=>$value===null?'':(new DateTimeImmutable($value))->format('d.m.Y');
$modeLabels=['pto_without_declaration'=>'ПТО внесён, декларация не внесена','without_pto'=>'ПТО не внесён','complete'=>'ПТО и декларация внесены','all'=>'Все'];
$query=['mode'=>$filters['mode'],'q'=>$filters['q'],'date'=>$filters['date'],'from'=>$filters['from'],'to'=>$filters['to'],'sort'=>$filters['sort']];
$mode=ViewSupport::choice('mode',$filters['mode'],$modeLabels,'Режим');
$dateChoice=ViewSupport::choice('date',$filters['date'],[''=>'Без периода','pto'=>'Дата ПТО','declaration'=>'Дата декларации'],'Дата для периода');
$sort=ViewSupport::choice('sort',$filters['sort'],[''=>'По умолчанию','pto_asc'=>'Старые даты ПТО первыми','pto_desc'=>'Новые даты ПТО первыми','object_asc'=>'По объекту'],'Порядок');
ViewSupport::begin($this,'ПТО и декларации',$identity,'completion-register');
?><div class="fm2-page-header"><div><h1>ПТО и декларации</h1><p>Внесённые в FMonitor сведения по документарному закрытию</p></div><span class="fm2-result-count"><?=(int)$filters['total']?> объектов</span></div>
<section class="fm2-directory-summary"><div><strong><?=$counters['pto_without_declaration']?></strong><span>ПТО без декларации</span></div><div><strong><?=$counters['without_pto']?></strong><span>Без записи ПТО</span></div><div><strong><?=$counters['complete']?></strong><span>Оба документа внесены</span></div><div><strong><?=$counters['all']?></strong><span>Всего в доступном охвате</span></div></section>
<section class="fm2-list-surface"><form method="get" action="/pilot/completion-register" class="fm2-user-toolbar"><label class="shlz-field"><span class="shlz-field__label">Поиск</span><span class="shlz-field__control"><input class="shlz-input" type="search" name="q" maxlength="120" value="<?=Html::encode($filters['q'])?>" placeholder="Адрес, регномер или реквизиты декларации"></span></label><?=$mode?><?=$dateChoice?><label class="shlz-field"><span class="shlz-field__label">С</span><input class="shlz-input" type="date" name="from" value="<?=Html::encode($filters['from'])?>"></label><label class="shlz-field"><span class="shlz-field__label">По</span><input class="shlz-input" type="date" name="to" value="<?=Html::encode($filters['to'])?>"></label><?=$sort?><button class="shlz-button shlz-button--primary" type="submit">Показать</button><a class="shlz-button shlz-button--secondary" href="/pilot/completion-register">Сбросить</a></form>
<?php if($rows===[]):?><p class="shlz-table__empty">По выбранным условиям записей в FMonitor не найдено. Это не означает отсутствие физического документа.</p><?php else:?><div class="shlz-table-wrap" data-mobile-strategy="contained-scroll" tabindex="0" aria-label="Реестр ПТО и деклараций"><table class="shlz-table"><thead class="shlz-table__head"><tr class="shlz-table__row"><th class="shlz-table__cell">Объект</th><th class="shlz-table__cell">Акт ПТО</th><th class="shlz-table__cell">Декларация</th><th class="shlz-table__cell">Состояние</th><th class="shlz-table__cell">Действие</th></tr></thead><tbody><?php foreach($rows as$row):?><tr class="shlz-table__row" data-object-id="<?=$row['objectId']?>"><td class="shlz-table__cell"><strong><?=Html::encode($row['registrationNumber']!==''?$row['registrationNumber']:'Объект #'.$row['objectId'])?></strong><small><?=Html::encode($row['address'])?><?=trim($row['entrance'])!==''?' · подъезд '.Html::encode($row['entrance']):''?></small></td><td class="shlz-table__cell"><?php if($row['ptoDate']===null):?>Не внесён в FMonitor<?php else:?><time datetime="<?=Html::encode($row['ptoDate'])?>"><?=$dateLabel($row['ptoDate'])?></time><?php if($row['declarationDate']===null):?><small><?=abs((int)$row['daysSincePto'])?> календарных дней от даты ПТО</small><?php endif;endif?></td><td class="shlz-table__cell"><?php if($row['declarationDate']===null):?>Не внесена в FMonitor<?php else:?><time datetime="<?=Html::encode($row['declarationDate'])?>"><?=$dateLabel($row['declarationDate'])?></time><small><?=Html::encode((string)$row['declarationDetails'])?></small><?php endif?></td><td class="shlz-table__cell"><?=$row['inconsistent']?'Ошибка сведений: декларация зарегистрирована без ПТО':($row['ptoDate']===null?'Сведения ПТО не зарегистрированы':($row['declarationDate']===null?'Ожидаются сведения декларации':'Документарные сведения внесены'))?></td><td class="shlz-table__cell"><a class="shlz-link" href="/pilot/objects/<?=$row['objectId']?>#completion"><?=$row['declarationDate']===null?'Внести / проверить документы':'Документы и история'?></a></td></tr><?php endforeach?></tbody></table></div><?php endif?>
<?=ViewSupport::pagination('/pilot/completion-register',(int)$filters['page'],(int)$filters['pages'],(int)$filters['total'],50,$query,'Страницы реестра ПТО и деклараций')?></section><?php ViewSupport::end($this);
